// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 amount, uint256 roll, uint256 warp) public {
        amount = 10 ether;
        vm.assume(roll > 0);
        vm.assume(warp > 0);
        vm.warp(warp);
        vm.roll(roll);

        address caller = address(0x1337);
        vm.deal(caller, amount);

        uint256 callerBefore = caller.balance;
        uint256 contractBefore = address(c).balance;

        vm.prank(caller);
        (bool ok, ) = address(c).call{value: amount}("");

        if (roll % 15 == 0) {
            assertTrue(ok);
            assertEq(address(c).balance, 0);
            assertEq(caller.balance, callerBefore + contractBefore);
        }
    }
}
